const FIT_UINT16 Profile::GetFieldIndex(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
{
    static FIT_UINT16 cachedMesgNum = FIT_UINT16_INVALID;
    static const MESG *cachedMesg = NULL;

    const MESG *mesg;
    if (mesgNum == cachedMesgNum)
        mesg = cachedMesg;
