const FIT_UINT16 Profile::GetFieldIndex(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
{
    static const MESG *mesgCache[65536] = {};
    static const MESG * const nullMesg = reinterpret_cast<const MESG*>(1);

    const MESG *mesg = mesgCache[mesgNum];
    if (mesg == NULL)
    {
        mesg = GetMesg(mesgNum);
        mesgCache[mesgNum] = mesg ? mesg : nullMesg;
    }
    if (mesg == nullMesg)
        return FIT_UINT16_INVALID;

    static FIT_UINT16 lastMesgNum = FIT_UINT16_INVALID;
    static unsigned long long fieldGen[256] = {};
    static FIT_UINT16 fieldIndex[256];
    static unsigned long long gen = 0;

    if (mesgNum != lastMesgNum)
    {
        lastMesgNum = mesgNum;
        ++gen;
    }

    if (fieldGen[fieldNum] == gen)
        return fieldIndex[fieldNum];

    const FIELD *fields = mesg->fields;
    const FIT_UINT16 numFields = mesg->numFields;
    for (FIT_UINT16 i = 0; i < numFields; ++i)
    {
        if (fields[i].num == fieldNum)
        {
            fieldGen[fieldNum] = gen;
            fieldIndex[fieldNum] = i;
            return i;
        }
    }

    fieldGen[fieldNum] = gen;
    fieldIndex[fieldNum] = FIT_UINT16_INVALID;
    return FIT_UINT16_INVALID;
}

